"""Inline demo page served at /demo (UI route only; API and webhook routes live at the origin root)."""
DEMO_HTML="""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Mouth Care Solutions</title><style>body{margin:0;background:#f5f8fb;color:#15324b;font:16px system-ui}header{background:#123d56;color:white;padding:28px 7%;display:flex;justify-content:space-between}main{max-width:1100px;margin:36px auto;padding:0 20px}.hero{background:#dff1ef;padding:38px;border-radius:22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:22px}.card{background:white;padding:24px;border-radius:18px;box-shadow:0 8px 22px #123d5612}button{background:#e56b4b;color:white;border:0;border-radius:10px;padding:12px 18px;cursor:pointer;margin:5px}input{padding:12px;border:1px solid #ccd9df;border-radius:8px;width:90%}#log{min-height:140px;white-space:pre-wrap;background:#102f42;color:#dcf6f0;padding:16px;border-radius:10px}.slot{display:inline-block;border:1px solid #9cc8c1;padding:10px;border-radius:10px;margin:4px}</style></head><body><header><b>MOUTH CARE SOLUTIONS</b><span>AI Receptionist Demo</span></header><main><section class="hero"><h1>Calm, clear support for your next dental visit.</h1><p>Ask about the clinic, explore approved service categories, or try a demo appointment flow.</p><button onclick="ask('What are your clinic hours?')">Ask clinic hours</button><button onclick="ask('What dental services are available?')">View services</button><button onclick="ask('I need an appointment')">Request appointment</button></section><div class="grid"><section class="card"><h2>Receptionist chat</h2><input id="q" placeholder="Type a question…"><button onclick="ask(document.getElementById('q').value)">Send</button><div id="log">Ready.</div></section><section class="card"><h2>Demo slots</h2><div id="slots">Loading…</div><h2>Human help</h2><input id="phone" placeholder="Phone number"><button onclick="callbackReq()">Request callback</button></section></div></main><script>const log=document.getElementById('log');window.addEventListener('unhandledrejection',()=>say('Something went wrong. Please try again or request a callback.'));function say(x){log.textContent=x+'\n\n'+log.textContent}async function ask(message){if(!message)return;const r=await fetch('/api/agent/session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message})});const d=await r.json();say('You: '+message+'\nReceptionist: '+d.text);if(d.slots)render(d.slots)}async function load(){const r=await fetch('/api/slots');if(!r.ok){document.getElementById('slots').textContent='Live appointment availability is not connected. Ask the receptionist or request a callback and the clinic team will confirm a time.';return}render((await r.json()).slots)}function render(slots){document.getElementById('slots').innerHTML=slots.map(s=>`<span class="slot">${new Date(s.starts_at).toLocaleString()}<br><button onclick="book('${s.id}')">Choose</button></span>`).join('')}async function book(id){const h=await fetch('/api/booking/hold',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({slot_id:id,session_id:'demo-browser',expiry_seconds:300})}).then(r=>r.json());const name=prompt('Your name (demo)');const phone=prompt('Your phone number (demo)');if(!name||!phone)return;const b=await fetch('/api/booking/confirm',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({hold_token:h.hold_token,patient_details:{name,phone},consent:true,idempotency_key:'browser-'+Date.now()})}).then(r=>r.json());say('Booking result: '+JSON.stringify(b));load()}async function callbackReq(){const phone=document.getElementById('phone').value;if(!phone)return say('Please enter a phone number.');const r=await fetch('/api/callback',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({patient_contact:phone,topic:'General assistance',preferred_window:'To be arranged'})});say('Callback request created: '+JSON.stringify(await r.json()))}load()</script></body></html>"""
